// Six main-thread tasks of ~120 ms each — a list re-measured on every render (long_tasks, tbt_ms):
const busy = (ms) => { const end = performance.now() + ms; while (performance.now() < end) {} };
for (let k = 0; k < 6; k += 1) setTimeout(() => busy(120), 50 + k * 200);
// The main content arrives late — the remount after a slow fetch (lcp_ms):
setTimeout(() => {
  const h = document.createElement('h1');
  h.textContent = 'Route ' + location.pathname + ' — ' + UNUSED.length + ' rows it never shows';
  const p = document.createElement('p');
  p.textContent = 'This paragraph is the largest contentful paint, and it arrives late. '.repeat(12);
  document.getElementById('root').append(h, p);
}, 2800);
// Content painted early, then pushed down by a banner inserted above it (cls):
const early = document.createElement('div');
early.style.cssText = 'height:300px;border:1px solid #d4d4d8;border-radius:8px';
early.innerHTML = '<span style="font-size:12px">Loading</span>';
document.getElementById('root').append(early);
setTimeout(() => {
  const banner = document.createElement('div');
  banner.style.cssText = 'height:360px;background:#fde68a';
  document.getElementById('root').prepend(banner);
}, 600);
